const agent = {{node:get_recovery_agent.data.data}};
const source = {{node:get_recovery_source.data.data}};
const text = value => value == null ? '' : String(value);
const suppliedAgent = text({{workflowparams:agent_id}});
const suppliedKey = text({{workflowparams:api_key}});
const sourceId = {{workflowparams:retry_task_id}};
if(typeof sourceId!=='string' || !/^\d+$/.test(sourceId)) throw new Error('Source task ID must be an exact digit string');
if(typeof source?.id==='number' && !Number.isSafeInteger(source.id)) throw new Error('Source task ID lost precision');
if(text(source?.id)!==sourceId) throw new Error('Source task ID mismatch');
if (!agent || !source || !suppliedKey || suppliedKey !== text(agent.api_key)) throw new Error('Recovery authorization failed');
if (!text(agent.tenant_id) || !text(agent.organization_id) || text(agent.agent_id)!==suppliedAgent || text(source.agent_id)!==suppliedAgent || text(source.organization_id)!==text(agent.organization_id) || text(source.tenant_id)!==text(agent.tenant_id)) throw new Error('Recovery scope mismatch');
if (source.status!=='FAILED' || !/^sync_[a-z_]+$/.test(text(source.task_type))) throw new Error('Recovery requires a failed outbound sync task');
if (!['SQL Accounting V2','AutoCount Accounting V2'].includes(agent.acc_integration_type)) throw new Error('Unsupported accounting integration');
const runId=text({{workflowparams:recovery_run_id}}), requestId=text({{workflowparams:recovery_request_id}});
if (![runId,requestId].every(v=>/^[A-Za-z0-9_-]{1,128}$/.test(v))) throw new Error('Invalid recovery correlation');
let original=source.payload == null ? '' : source.payload;
if (typeof original!=='string') throw new Error('Original payload must be a string');
for(let depth=0;depth<8;depth++) {
 let parsed; try { parsed=JSON.parse(original); } catch { break; }
 if (!parsed || typeof parsed!=='object' || !parsed.sync_recovery) break;
 if (typeof parsed.original_payload!=='string') throw new Error('Invalid predecessor envelope');
 original=parsed.original_payload;
 if(depth===7) throw new Error('Nested predecessor envelope limit');
}
return {payload:JSON.stringify({sync_recovery:{run_id:runId,request_id:requestId,source_task_id:sourceId},original_payload:original}),integration:agent.acc_integration_type};

const sql={{node:add_recovery_sql.data.id}}, atc={{node:add_recovery_atc.data.id}};
const values=[sql,atc].flatMap(v=>Array.isArray(v)?v:[v]).filter(v=>v!=null && v!=='');
if(values.length!==1 || (typeof values[0]==='number' && !Number.isSafeInteger(values[0])) || !/^\d+$/.test(String(values[0]))) throw new Error('Recovery create outcome is uncertain');
const taskId=String(values[0]);
const raw={{node:get_recovery_queue.data}};
const ids=raw==null || raw==='' ? [] : (typeof raw==='string'?JSON.parse(raw):raw);
if(!Array.isArray(ids) || ids.some(id=>(typeof id==='number' && !Number.isSafeInteger(id)) || !/^\d+$/.test(String(id)))) throw new Error('Invalid queue shape; do not repeat task creation');
return {task_id:taskId,taskArray:[...new Set([...ids.map(String),taskId])]};

